CREATE  VIEW  PRGANBARGRP AS SELECT        dbo.QPROGPASS2.CODB, dbo.MOGUDI_KOL_ANBARHA.NAME, dbo.QPROGPASS2.VAHED, dbo.QPROGPASS2.SumOfKOLMAV AS kolm,  dbo.MOGUDI_KOL_ANBARHA.MANDAH, dbo.STUF_DEF.MIN_M, dbo.MOGUDI_KOL_ANBARHA.MANDAH - dbo.STUF_DEF.MIN_M AS MOGMOG,  dbo.QPROGPASS2.CODB AS Expr1, dbo.QPROGPASS2.GRP,  dbo.UIIF(dbo.QPROGPASS2.SumOfKOLMAV * dbo.QPROGPASS2.SumOfKOLMAV - (dbo.MOGUDI_KOL_ANBARHA.MANDAH - dbo.STUF_DEF.MIN_M), N'>', 0,  dbo.QPROGPASS2.SumOfKOLMAV * dbo.QPROGPASS2.SumOfKOLMAV - (dbo.MOGUDI_KOL_ANBARHA.MANDAH - dbo.STUF_DEF.MIN_M), 0) AS sef,  dbo.UIIF(dbo.QPROGPASS2.SumOfKOLMAV * dbo.QPROGPASS2.SumOfKOLMAV - (dbo.MOGUDI_KOL_ANBARHA.MANDAH - dbo.STUF_DEF.MIN_M), N'<', 0,  (dbo.QPROGPASS2.SumOfKOLMAV * dbo.QPROGPASS2.SumOfKOLMAV - (dbo.MOGUDI_KOL_ANBARHA.MANDAH - dbo.STUF_DEF.MIN_M)) * - 1, 0)  AS EZAF, AVG(dbo.QPROGPASS2.SumOfMABL / dbo.QPROGPASS2.SumOfKOLMAV) AS mab, SUM(dbo.QPROGPASS2.SumOfMABLK) AS mablk FROM            dbo.MOGUDI_KOL_ANBARHA INNER JOIN  dbo.STUF_DEF ON dbo.MOGUDI_KOL_ANBARHA.CODE = dbo.STUF_DEF.CODE INNER JOIN  dbo.QPROGPASS2 ON dbo.MOGUDI_KOL_ANBARHA.CODE = dbo.QPROGPASS2.CODB GROUP BY dbo.QPROGPASS2.CODB, dbo.MOGUDI_KOL_ANBARHA.NAME, dbo.QPROGPASS2.VAHED, dbo.QPROGPASS2.SumOfKOLMAV,  dbo.MOGUDI_KOL_ANBARHA.MANDAH, dbo.STUF_DEF.MIN_M, dbo.MOGUDI_KOL_ANBARHA.MANDAH - dbo.STUF_DEF.MIN_M, dbo.QPROGPASS2.GRP,  dbo.UIIF(dbo.QPROGPASS2.SumOfKOLMAV * dbo.QPROGPASS2.SumOfKOLMAV - (dbo.MOGUDI_KOL_ANBARHA.MANDAH - dbo.STUF_DEF.MIN_M), N'>', 0,  dbo.QPROGPASS2.SumOfKOLMAV * dbo.QPROGPASS2.SumOfKOLMAV - (dbo.MOGUDI_KOL_ANBARHA.MANDAH - dbo.STUF_DEF.MIN_M), 0),  dbo.UIIF(dbo.QPROGPASS2.SumOfKOLMAV * dbo.QPROGPASS2.SumOfKOLMAV - (dbo.MOGUDI_KOL_ANBARHA.MANDAH - dbo.STUF_DEF.MIN_M), N'<', 0,  (dbo.QPROGPASS2.SumOfKOLMAV * dbo.QPROGPASS2.SumOfKOLMAV - (dbo.MOGUDI_KOL_ANBARHA.MANDAH - dbo.STUF_DEF.MIN_M)) * - 1, 0) HAVING (dbo.QPROGPASS2.SumOfKOLMAV <> 0) 
